const SIZE = 4;
// each instruction: either a normal op, or a jump to a target address
const program = {
  200: { op: 'LOAD R0, 50' },
  204: { op: 'ADD R0, R1' },
  208: { op: 'STORE R0, 60' }, // try: { op: 'JUMP 200', jumpTo: 200 }
};
let pc = 200;
for (let i = 0; i < 3; i++) {
  const instr = program[pc];
  if (!instr) break;
  console.log('fetch PC=' + pc + '  ->  ' + instr.op);
  // execute, then update the PC
  pc = instr.jumpTo !== undefined ? instr.jumpTo : pc + SIZE;
}
console.log('final PC=' + pc);
